pid_t pid = fork();
int status;

if (pid < 0) {
    // Fork failure
}

if (pid == 0) {
    // CHILD PROCESS
    // Replace process image (exec)
    char *args[] = {"/bin/echo", "Hi", NULL};
    execv(args[0], args);

    // Only returns on error
    _exit(127);
} else {
    // PARENT PROCESS
    waitpid(pid, &status, 0);

    if (WIFEXITED(status)) {
        int exit_code = WEXITSTATUS(status);
    }
}
